          "ਮੇਲੇ ਵਿੱਚ ਬਜ਼ਾਰ ਸਜਦਾ ਹੈ, ਜਿੱਥੇ ਖਾਣ-ਪੀਣ, ਚੂੜੀਆਂ, ਖਿਡੌਣੇ ਅਤੇ ਕਲਾਕਾਰਾਂ ਦੀਆਂ ਵਸਤਾਂ ਮਿਲਦੀਆਂ ਹਨ।"
