          "ਅਨੰਦਪੁਰ ਸਾਹਿਬ ਵਿੱਚ ਹੋਲੀ ਤੋਂ ਅਗਲੇ ਦਿਨ ਹੋਲਾ-ਮਹੱਲਾ ਮਨਾਇਆ ਜਾਂਦਾ ਹੈ, ਜਿੱਥੇ ਗੁਰੂ ਗੋਬਿੰਦ ਸਿੰਘ ਜੀ ਖ਼ਾਲਸੇ ਨੂੰ ਯੁੱਧ-ਕਲਾ ਵਿੱਚ ਨਿਪੁੰਨ ਕਰਨ ਲਈ ਦੋ ਦਲਾਂ ਵਿੱਚ ਨਕਲੀ ਲੜਾਈ ਕਰਵਾਉਂਦੇ ਸਨ।"
