        { heading: "ਹੋਰ ਮੇਲੇ ਅਤੇ ਤਿਉਹਾਰ", points: [
          "ਤਰਨਤਾਰਨ ਵਿੱਚ ਭਾਦੋਂ ਦੀ ਮੱਸਿਆ ਦਾ ਭਾਰੀ ਮੇਲਾ ਲੱਗਦਾ ਹੈ; ਸਾਹਿਬਜ਼ਾਦਿਆਂ ਦੀ ਸ਼ਹੀਦੀ ਵਾਲੀਆਂ ਥਾਵਾਂ ਮੋਰਿੰਡਾ, ਚਮਕੌਰ ਸਾਹਿਬ ਅਤੇ ਫ਼ਤਿਹਗੜ੍ਹ ਸਾਹਿਬ ਵਿੱਚ ਜੋੜ-ਮੇਲੇ ਹੁੰਦੇ ਹਨ।",
          "ਕਵੀਆਂ ਦੀ ਯਾਦ ਵਿੱਚ ਵੀ ਮੇਲੇ ਲੱਗਦੇ ਹਨ, ਜਿਵੇਂ ਜਗਦੇਵ ਕਲਾਂ ਵਿੱਚ ਹਾਸ਼ਮ ਸ਼ਾਹ ਅਤੇ ਲੁਧਿਆਣੇ ਵਿੱਚ ਪ੍ਰੋ. ਮੋਹਨ ਸਿੰਘ ਦੀ ਯਾਦ ਵਿੱਚ।",
          "ਲੋਹੜੀ ਤੋਂ ਅਗਲੇ ਦਿਨ ਮਾਘੀ (ਮਕਰ ਸੰਕ੍ਰਾਂਤੀ) ਆਉਂਦੀ ਹੈ; ਫੱਗਣ ਦੀ ਮੱਸਿਆ ਨੂੰ ਸ਼ਿਵਰਾਤਰੀ ਮਨਾਈ ਜਾਂਦੀ ਹੈ ਅਤੇ ਅੱਜ-ਕੱਲ੍ਹ ਕੁੜੀਆਂ ਦੀ ਲੋਹੜੀ ਵੀ ਮਨਾਈ ਜਾਂਦੀ ਹੈ।"
        ] }
