        { term: "ਬਹਿੜੀਏ", meaning: "ਜਰਗ ਦੇ ਮੇਲੇ ਵਿੱਚ ਦੇਵੀ ਨੂੰ ਚੜ੍ਹਾਏ ਜਾਂਦੇ ਬੇਹੇ ਗੁਲਗੁਲੇ।" }
