      summary: "ਸੁਖਦੇਵ ਮਾਦਪੁਰੀ ਦਾ ਲੇਖ ਦੱਸਦਾ ਹੈ ਕਿ ਲੋਕ-ਖੇਡਾਂ ਪੇਂਡੂ ਜੀਵਨ ਦਾ ਅਨਿੱਖੜਵਾਂ ਅੰਗ ਹਨ, ਇਹ ਸਰੀਰ ਅਤੇ ਮਨ ਦਾ ਵਿਕਾਸ ਕਰਦੀਆਂ ਹਨ ਅਤੇ ਬੱਚਿਆਂ ਤੇ ਗੱਭਰੂਆਂ ਦੀਆਂ ਕਈ ਪ੍ਰਸਿੱਧ ਖੇਡਾਂ ਦਾ ਜ਼ਿਕਰ ਕਰਦਾ ਹੈ।",
