          "'ਪੁੱਗਣ' ਅਤੇ ਆੜੀ ਚੁਣਨ ਵੇਲੇ ਬੱਚੇ ਲੈਅ ਵਾਲੇ ਗੀਤ ਗਾਉਂਦੇ ਹਨ ਜਿਨ੍ਹਾਂ ਵਿੱਚ ਗਿਣਤੀ ਅਤੇ ਤੁਕਾਂਤ ਹੁੰਦੇ ਹਨ।",
