          "ਇਸ ਵਿੱਚ ਪੇਸ਼ੇਵਰ ਨਕਲੀਏ ਭੇਸ ਬਦਲੇ ਬਿਨਾਂ ਚੁਸਤ, ਹਾਜ਼ਰ-ਜਵਾਬੀ ਅਤੇ ਵਿਅੰਗ ਭਰੇ ਵਾਰਤਾਲਾਪ ਨਾਲ ਕਿਸੇ ਪੇਸ਼ੇ, ਮਨੁੱਖ ਜਾਂ ਜਾਤ ਬਾਰੇ ਕਹਾਣੀ ਖੁੱਲ੍ਹੇ ਪਿੜ ਵਿੱਚ ਪੇਸ਼ ਕਰਦੇ ਹਨ।",
