          "ਪੇਸ਼ਕਾਰੀ ਸਮੂਹਿਕ ਅਤੇ ਖੁੱਲ੍ਹੇ ਚਰਿੱਤਰ ਦੀ ਹੁੰਦੀ ਹੈ; ਸਿਰਫ਼ ਇੱਕ ਛੋਟਾ ਤਬਲਾ ਖੱਬੇ ਹੱਥ ਵਿੱਚ ਹੁੰਦਾ ਹੈ ਅਤੇ ਬਾਕੀ ਕੰਮ ਇਸ਼ਾਰਿਆਂ ਨਾਲ ਸਾਰ ਲਿਆ ਜਾਂਦਾ ਹੈ।",
