          "ਨਕਲਾਂ ਵਿੱਚ ਦਰਸ਼ਕਾਂ ਦੀ ਅਹਿਮ ਭੂਮਿਕਾ ਹੁੰਦੀ ਹੈ; ਸਮੇਂ, ਥਾਂ ਤੇ ਪ੍ਰਸੰਗ ਬਦਲਣ ਨਾਲ ਇਹਨਾਂ ਦੀ ਸਾਰਥਕਤਾ ਘੱਟ-ਵੱਧ ਹੁੰਦੀ ਰਹਿੰਦੀ ਹੈ।"
