        { term: "ਭੰਡ", meaning: "ਨਕਲਾਂ ਨਾਲ ਜੁੜੀ ਇੱਕ ਖ਼ਾਸ ਜਾਤ ਅਤੇ ਉਸ ਦੇ ਕਲਾਕਾਰ।" }
