          "**ਸੰਯੁਕਤ ਵਾਕ**: ਦੋ ਜਾਂ ਵੱਧ ਸੁਤੰਤਰ ਉਪਵਾਕ ਸਮਾਨ ਯੋਜਕਾਂ (ਅਤੇ, ਪਰ, ਜਾਂ, ਸਗੋਂ, ਪਰੰਤੂ) ਨਾਲ ਜੁੜੇ ਹੁੰਦੇ ਹਨ।",
          "**ਮਿਸ਼ਰਿਤ ਵਾਕ**: ਇੱਕ ਮੁੱਖ ਉਪਵਾਕ ਅਤੇ ਇੱਕ ਜਾਂ ਵੱਧ ਅਧੀਨ ਉਪਵਾਕ ਹੁੰਦੇ ਹਨ; ਅਧੀਨ ਉਪਵਾਕ ਇਕੱਲਾ ਅਰਥ ਨਹੀਂ ਦਿੰਦਾ।"
