          "ਪਾਠ ਦੀਆਂ ਉਦਾਹਰਨਾਂ: ਮਿਸ਼ਰਿਤ ਤੋਂ ਸੰਯੁਕਤ ('ਭਾਵੇਂ ਤੁਸੀਂ ਦੌਲਤਮੰਦ ਹੋ ਤਾਂ ਵੀ ਸੁਖੀ ਨਹੀਂ' → 'ਤੁਸੀਂ ਦੌਲਤਮੰਦ ਹੋ ਪਰ ਸੁਖੀ ਨਹੀਂ'); ਹਾਂ-ਵਾਚਕ ਤੋਂ ਨਾਂਹ-ਵਾਚਕ ('ਮਿਹਨਤ ਸਫ਼ਲ ਹੋਈ' → 'ਮਿਹਨਤ ਵਿਅਰਥ ਨਹੀਂ ਗਈ'); ਪ੍ਰਸ਼ਨ ਤੋਂ ਸਧਾਰਨ ('ਤੁਹਾਡਾ ਨਾਂ ਕੀ ਹੈ?' → 'ਤੁਸੀਂ ਆਪਣਾ ਨਾਂ ਦੱਸੋ।')।",
