      summary: "ਅਖਾਉਤਾਂ (ਅਖਾਣ ਜਾਂ ਕਹਾਵਤਾਂ) ਲੋਕ-ਸੂਝ ਦਾ ਭੰਡਾਰ ਹੁੰਦੀਆਂ ਹਨ। ਇਸ ਪਾਠ ਵਿੱਚ ਅਖਾਉਤਾਂ ਦੀ ਮਹੱਤਤਾ ਅਤੇ ਕੁਝ ਅਖਾਉਤਾਂ ਦੇ ਅਰਥ ਤੇ ਵਰਤੋਂ ਵਾਕਾਂ ਵਿੱਚ ਦਿੱਤੇ ਗਏ ਹਨ।",
