          "ਉਹਨਾਂ ਨੇ ਸਵੈ-ਅਧਿਐਨ ਰਾਹੀਂ ਭਾਰਤੀ ਤੇ ਵਿਦੇਸ਼ੀ ਸਾਹਿਤ ਪੜ੍ਹਿਆ ਅਤੇ ਕਵਿਤਾ ਨੂੰ ਨਵੇਂ ਤੋਲ-ਤੁਕਾਂਤ ਅਤੇ ਛੰਦਾਂ ਵਿੱਚ ਲਿਖ ਕੇ ਰੂਪ ਅਤੇ ਵਿਸ਼ੇ ਦੋਹਾਂ ਪੱਖਾਂ ਤੋਂ ਆਧੁਨਿਕ ਬਣਾਇਆ।",
