          "'ਕਰੇਵਾ' ਕਸ਼ਮੀਰ ਦੇ ਉੱਚੇ ਟਿੱਬਿਆਂ ਦੀਆਂ ਪੱਧਰਾਂ ਨੂੰ ਕਹਿੰਦੇ ਹਨ।"
