        { q: "ਕਵਿਤਾ ਦਾ ਕੇਂਦਰੀ ਭਾਵ ਲਿਖੋ।", a: "ਕਵਿਤਾ ਦਾ ਕੇਂਦਰੀ ਭਾਵ ਕਸ਼ਮੀਰ ਦੀ ਅਲੌਕਿਕ ਸੁੰਦਰਤਾ ਦੀ ਸਿਫ਼ਤ ਹੈ, ਜੋ ਧਰਤੀ 'ਤੇ ਹੁੰਦੇ ਹੋਏ ਵੀ ਅਸਮਾਨੀ ਛੂਹ ਵਾਲੀ ਹੈ।" },
        { q: "ਭਾਈ ਵੀਰ ਸਿੰਘ ਨੂੰ ਆਧੁਨਿਕ ਪੰਜਾਬੀ ਸਾਹਿਤ ਦਾ ਪਿਤਾਮਾ ਕਿਉਂ ਕਿਹਾ ਜਾਂਦਾ ਹੈ?", a: "ਉਹਨਾਂ ਨੇ ਪੰਜਾਬੀ ਕਵਿਤਾ ਨੂੰ ਨਵੇਂ ਤੋਲ-ਤੁਕਾਂਤ, ਛੰਦਾਂ ਅਤੇ ਨਵੇਂ ਵਿਸ਼ਿਆਂ ਰਾਹੀਂ ਰੂਪ ਤੇ ਵਿਸ਼ੇ ਪੱਖੋਂ ਆਧੁਨਿਕ ਲੀਹਾਂ 'ਤੇ ਤੋਰਿਆ।" }
