          "ਜਿੰਦਾਂ ਮਿਲੀਆਂ ਰਹਿਣ ਕਿਉਂਕਿ ਮਿਲਿਆਂ ਜਿਊਂਦੀਆਂ ਹਨ ਅਤੇ ਵਿੱਛੜਿਆਂ ਮਰਦੀਆਂ ਹਨ।",
