          "ਮੈਂ ਤੁਰਦਾ ਹੀ ਰਹਾਂ ਕਿਉਂਕਿ ਤੁਰਿਆਂ ਵਧਦਾ ਹਾਂ ਅਤੇ ਖਲੋਇਆਂ ਘਟਦਾ ਹਾਂ।"
