        { q: "ਡਾ. ਦੀਵਾਨ ਸਿੰਘ ਨਾਲ 'ਕਾਲੇਪਾਣੀ' ਉਪਨਾਮ ਕਿਵੇਂ ਜੁੜਿਆ?", a: "ਉਹਨਾਂ ਦੀ ਬਦਲੀ ਅੰਡੇਮਾਨ ਟਾਪੂਆਂ ਵਿੱਚ ਹੋਈ, ਜਿਸ ਨੂੰ ਉਸ ਸਮੇਂ ਕਾਲੇਪਾਣੀ ਕਿਹਾ ਜਾਂਦਾ ਸੀ।" }
