          "ਉਹ ਕਈ ਮਹਿਕਮਿਆਂ ਵਿੱਚ ਅਧਿਕਾਰੀ ਅਤੇ ਪੰਜਾਬੀ ਯੂਨੀਵਰਸਿਟੀ ਵਿੱਚ ਪੱਤਰਕਾਰੀ ਦੇ ਪ੍ਰੋਫ਼ੈਸਰ ਰਹੇ; 'ਪੰਜਾਬੀ ਟ੍ਰਿਬਿਊਨ' ਅਤੇ 'ਦੇਸ਼ ਸੇਵਕ' ਦੇ ਸੰਪਾਦਕ ਵੀ ਰਹੇ।",
