          "ਅਨੰਦ-ਕਾਰਜ ਸਮੇਂ ਰਾਗੀ ਦੀ ਵੈਰਾਗ ਭਰੀ ਆਵਾਜ਼ ਸਭ ਨੂੰ ਰੁਲਾ ਦਿੰਦੀ ਹੈ ਪਰ ਵੀਰ ਆਪਣੀ ਉਦਾਸੀ ਛੁਪਾਉਣ ਲਈ ਗਾਉਣ ਵਾਲੇ ਨੂੰ ਝਿੜਕ ਕੇ ਚੁੱਪ ਕਰਵਾ ਦਿੰਦਾ ਹੈ ਅਤੇ ਰੋਂਦੀ ਜੀਤੋ ਨੂੰ ਵੀ 'ਮੂਰਖ ਨਹੀਂ ਬਣੀਂਦਾ' ਕਹਿ ਦਿੰਦਾ ਹੈ।",
          "ਵਿਦਾਇਗੀ ਵੇਲੇ ਜੀਤੋ ਰੋਂਦੀ ਹੋਈ ਕਾਰ ਤੱਕ ਨਹੀਂ ਜਾਂਦੀ; ਵੀਰ ਅਖ਼ੀਰ ਵਿੱਚ ਸਲਾਮੀ ਦਿੰਦਾ ਹੈ, ਪਿਛਲੀਆਂ ਯਾਦਾਂ ਯਾਦ ਕਰਦਾ ਹੈ ਅਤੇ ਸਾਰੇ ਪੈਸੇ ਜੀਤੋ ਦੇ ਹੱਥ ਰੱਖ ਦਿੰਦਾ ਹੈ।",
