      summary: "ਡਾ. ਦਲੀਪ ਕੌਰ ਟਿਵਾਣਾ ਦੀ ਕਹਾਣੀ 'ਸਤੀਆ ਸੇਈ' ਵਿੱਚ ਲੇਖਿਕਾ ਰੇਲਗੱਡੀ ਵਿੱਚ ਇੱਕ ਮੰਗਤੇ ਦੇ ਗੀਤ ਤੋਂ ਪ੍ਰੇਰਿਤ ਹੋ ਕੇ ਭਗਤ ਸਿੰਘ ਦੀ ਮੰਗੇਤਰ ਨਾਲ ਕਲਪਿਤ ਮਿਲਣੀ ਰਾਹੀਂ ਉਸ ਦੇ ਵਿਛੋੜੇ, ਸਿਦਕ ਅਤੇ ਸਾਹਸ ਦਾ ਚਿਤਰਨ ਕਰਦੀ ਹੈ।",
